import sys

def main():
    flags = []
    filename = None
    args = sys.argv[1:]
    i = 0
    while i < len(args):
        arg = args[i]
        if arg.startswith('-'):
            flags.extend(arg)
        else:
            filename = arg
        i += 1

    read_chars = 'c' in flags
    read_words = 'w' in flags
    read_lines = 'l' in flags

    if not flags:
        read_chars = True
        read_words = True
        read_lines = True

    # Determine the order: l, w, c (lines, words, characters)
    order = []
    if read_lines:
        order.append('l')
    if read_words:
        order.append('w')
    if read_chars:
        order.append('c')

    # Read input
    if filename is None or filename == '-':
        data = sys.stdin.buffer.read()
    else:
        with open(filename, 'rb') as f:
            data = f.read()

    num_bytes = len(data)
    num_words = len(data.split()) if data else 0
    # Lines: split on newlines; a final line without trailing newline still counts
    if data == b'':
        num_lines = 0
    else:
        num_lines = data.count(b'\n')
        if not data.endswith(b'\n'):
            num_lines += 1

    results = []
    for flag in order:
        if flag == 'l':
            results.append(str(num_lines))
        elif flag == 'w':
            results.append(str(num_words))
        elif flag == 'c':
            results.append(str(num_bytes))

    print(' '.join(results))

if __name__ == '__main__':
    main()
